use super::*;

/// Put `current` back to `previous`. Local to the device, so it works with the workstation gone.
pub fn revert(device: &Device, name: &str) -> Result<(), String> {
    let script = format!(
        "r=$HOME/{REMOTE_ROOT}; \
         [ -L \"$r/{name}.previous\" ] || {{ echo 'no previous'; exit 1; }}; \
         cp -P \"$r/{name}.previous\" \"$r/{name}.current.tmp\" && mv -T \"$r/{name}.current.tmp\" \"$r/{name}.current\" && echo OK"
    );
    ssh(device, &script).map(|_| ())
}
